#!/usr/bin/env python3
"""news-image-20261126 — The World Today, Thursday 26 November 2026.

One lead story, five supporting stories and a sport strip, plus nine
one-line briefs in the JUGA HARI INI footer: the day in one image.
The finished front page travels inside this file as base64 text. When
the program runs it decodes that text and writes the resulting JPEG
bytes, untouched, to entry.png in the output directory, so the output
is identical on every run. Nothing here needs the network or any
input; it is the Python 3.13 standard library only.
"""

import base64
import os

# One long line of data: the front page as a JPEG, base64-encoded.
# It is the picture itself, not program logic — write_entry() decodes
# it verbatim each time the program runs.
IMAGE_B64 = ""

OUTPUT_NAME = "entry.png"


def output_dir():
    """The grader's output directory: $MAKEFUN_OUTPUT_DIR, else /output."""
    return os.environ.get("MAKEFUN_OUTPUT_DIR", "/output")


def write_entry():
    """Decode the embedded page and write it to the output directory."""
    data = base64.b64decode(IMAGE_B64)
    target_dir = output_dir()
    os.makedirs(target_dir, exist_ok=True)
    path = os.path.join(target_dir, OUTPUT_NAME)
    with open(path, "wb") as handle:
        handle.write(data)
    return path


def main():
    write_entry()


if __name__ == "__main__":
    main()
